#!/usr/bin/env bash
set -Eeuo pipefail
# C01 Residual
# DTD / ResNet-50 / 100 ep
# Planning estimate: 6.0–8.5 h
# Strict wall-clock policy: planner = 9h30 from this shell start; hard kill = 9h50.
# One scientific method only in this session; no hidden second task.
export PACK_SESSION_START_EPOCH="$(date +%s)"
export PACK_SAFE_MINUTES=570
export PACK_RESERVE_MINUTES=20
export PACK_SAFETY_FACTOR=1.25
export DT1D_CNN_COMMIT="${DT1D_CNN_COMMIT:-fda0047228b3cf048ebb43d93f3970574fbef9ef}"
export TASK_ID="C01_residual"
HARD_SECONDS=$((9*3600 + 50*60))
TMP="/kaggle/working/${TASK_ID}_under10h_payload.sh"

cat > "$TMP.b64" <<'PAYLOAD_B64'

PAYLOAD_B64
base64 -d "$TMP.b64" > "$TMP"
chmod +x "$TMP"
rm -f "$TMP.b64"

# Enforce a real hard ceiling. If reached, completed LR/seed units are packed and reusable.
set +e
timeout --signal=TERM --kill-after=60s "$HARD_SECONDS" bash "$TMP"
rc=$?
set -e

# Belt-and-suspenders repack after a timeout or unusual child exit.
python - <<'PY_REPACK'
import os, zipfile
from pathlib import Path
sid=os.environ.get('TASK_ID','')
root=Path('/kaggle/working')/f'progress_{sid}'
out=Path('/kaggle/working')/f'{sid}_results.zip'
if root.is_dir():
    out.unlink(missing_ok=True)
    with zipfile.ZipFile(out,'w',zipfile.ZIP_DEFLATED,compresslevel=6) as z:
        for p in root.rglob('*'):
            if p.is_file() and p.suffix.lower() not in {'.pth','.pt','.ckpt'}:
                z.write(p,p.relative_to(root.parent))
    print('REPACKED',out)
PY_REPACK

if [[ "$rc" == "124" || "$rc" == "137" || "$rc" == "143" ]]; then
  echo "HARD_STOP_UNDER_10H: session stopped before 10h."
  echo "Attach /kaggle/working/${TASK_ID}_results.zip to a fresh Kaggle session and rerun THIS SAME file."
  exit 0
fi
exit "$rc"
